sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var caseId = steps('{{step['186209e9c1304978ad4275077649be48'].record_id}}');
    var slaGR = new GlideRecord('task_sla');
    slaGR.addQuery('task', caseId);
    slaGR.query();
    var count = slaGR.getRowCount();
    assertEqual({
        name: 'SLA record exists after state transition',
        shouldbe: 'true',
        value: String(count > 0)
    });
    stepResult.setOutputMessage('Found ' + count + ' task_sla record(s) after transition to In Progress');
})(outputs, steps, params, stepResult, assertEqual);

